/* global Ext, I18n, Banks, BankRates, CurrencyParse, CurrencyConvert */
"use strict";

// Runs as the Firefox background page and inside Chrome's service worker
// (sw.js, generated by scripts/build.mjs, importScripts the same files).

const ext = Ext.api;
const ROOT_ID = "cv-root";
// lastForeign: the foreign currency last converted to or from MDL, used by
// the keyboard shortcut for amounts in lei.
const DEFAULTS = { bank: Banks.DEFAULT, lang: "auto", lastForeign: "EUR" };

// ---------------------------------------------------------------------------
// Settings and strings

const settingsArea = () => ext.storage.sync || ext.storage.local;

async function getSettings() {
  const s = await settingsArea()
    .get(DEFAULTS)
    .catch(() => ({ ...DEFAULTS }));
  if (!Banks.get(s.bank)) s.bank = Banks.DEFAULT;
  return s;
}

async function saveSettings(changes) {
  const clean = {};
  if (changes.bank && Banks.get(changes.bank)) clean.bank = changes.bank;
  if (changes.lang === "auto" || I18n.LANGS.includes(changes.lang)) clean.lang = changes.lang;
  if (/^[A-Z]{3}$/.test(changes.lastForeign || "") && changes.lastForeign !== "MDL") clean.lastForeign = changes.lastForeign;
  if (Object.keys(clean).length) await settingsArea().set(clean);
}

// Settings, language, translator and the selected bank, for one event.
async function context() {
  const settings = await getSettings();
  const { lang, t } = await I18n.load(settings.lang);
  return { settings, lang, t, bank: Banks.get(settings.bank) };
}

// The picker can use a longer name ("BNM (official rate)"); sentences use bank.name.
const bankList = (t) => Banks.all().map((b) => ({ id: b.id, name: b.nameKey ? t(b.nameKey) : b.name }));

// Strings for lib/view.js. "copied" and "updatedAgo" keep their $1 for the view to fill.
const VIEW_STRINGS = [
  "appName", "boxLabel", "close", "refresh", "settings", "bankLabel", "fromLabel", "toLabel", "swap", "amountLabel",
  "enterAmount", "ambiguousNote", "srcGuessed", "copyHint", "copied", "copyFailed", "best", "justNow", "updatedAgo",
  "publishedRates",
];

const viewStrings = (t) => Object.fromEntries(VIEW_STRINGS.map((k) => [k, t(k)]));

function errorText(err, bank, t) {
  const { name } = bank;
  switch (err.code) {
    case "layout":
      return t("errLayout", name);
    case "blocked":
      return t("errBlocked", name);
    case "busy":
      return t("errBusy", name);
    case "timeout":
      return t("errTimeout", name);
    case "http":
      return t("errHttp", name, err.detail);
    case "network":
      return t("errNetwork", name);
    default:
      return t("errGeneric", err.detail);
  }
}

// ---------------------------------------------------------------------------
// Context menu.
//
// Firefox rebuilds it each time it opens, around the selection ("Convert
// 1.234,56 EUR to ▸ …"). Chrome can't, so it gets a static "Convert “%s”
// to ▸ …" menu and the box works out the source currency.

const menuTitle = (s) => s.replace(/&/g, "&&");
const currencyLabel = (code, lang) => `${code} · ${CurrencyConvert.currencyName(code, lang)}`;
const createMenu = (props) => Ext.createMenu({ contexts: ["selection"], ...props });

// -> { all: every currency the bank quotes, menu: the popular ones to list }
async function bankCurrencies(bank) {
  const cached = await BankRates.readCache(bank.id).catch(() => null);
  const rates = cached && cached.rates;
  return { all: CurrencyConvert.availableCurrencies(rates), menu: CurrencyConvert.menuCurrencies(rates) };
}

function addTargets(parentId, src, codes, lang) {
  for (const dst of codes) {
    if (dst !== src) createMenu({ id: `conv:${src}:${dst}`, parentId, title: currencyLabel(dst, lang) });
  }
}

function addSources(parentId, idPrefix, codes, exclude, lang) {
  for (const src of codes) {
    if (src === exclude) continue;
    const id = `${idPrefix}:${src}`;
    createMenu({ id, parentId, title: currencyLabel(src, lang) });
    addTargets(id, src, codes, lang);
  }
}

function addSettingsItem(t, bank) {
  createMenu({ id: "cv-sep-settings", parentId: ROOT_ID, type: "separator" });
  createMenu({ id: "cv-settings", parentId: ROOT_ID, title: menuTitle(t("menuSettings", bank.name)) });
}

// Firefox: returns false if a newer menu opened while this one was being built.
async function rebuildMenu(selectionText, isCurrent = () => true) {
  const parsed = CurrencyParse.parseSelection(selectionText || "");
  const { lang, t, bank } = await context();
  const { all, menu: codes } = await bankCurrencies(bank);
  if (!isCurrent()) return false;

  await Ext.removeAllMenus();
  if (!parsed) {
    createMenu({ id: ROOT_ID, title: t("appName"), visible: false });
  } else if (parsed.currency && all.includes(parsed.currency)) {
    const src = parsed.currency;
    createMenu({ id: ROOT_ID, title: menuTitle(t("menuConvertTo", `${parsed.text} ${src}`)) });
    addTargets(ROOT_ID, src, codes, lang);
    createMenu({ id: "cv-sep", parentId: ROOT_ID, type: "separator" });
    createMenu({ id: "alt", parentId: ROOT_ID, title: t("menuTreatAs") });
    addSources("alt", "alt", codes, src, lang);
    addSettingsItem(t, bank);
  } else {
    createMenu({ id: ROOT_ID, title: menuTitle(t("menuConvertFrom", parsed.text)) });
    addSources(ROOT_ID, "src", codes, null, lang);
    addSettingsItem(t, bank);
  }
  return isCurrent();
}

// Chrome: one static menu for every selection. Builds run one at a time so a
// settings change and a rates refresh can't interleave their items.
let menuBuild = Promise.resolve();

function buildStaticMenu() {
  const build = async () => {
    const { lang, t, bank } = await context();
    const { menu: codes } = await bankCurrencies(bank);
    await Ext.removeAllMenus();
    createMenu({ id: ROOT_ID, title: t("menuConvertSelection") });
    for (const dst of codes) createMenu({ id: `to:${dst}`, parentId: ROOT_ID, title: currencyLabel(dst, lang) });
    addSettingsItem(t, bank);
  };
  menuBuild = menuBuild.then(build, build);
  return menuBuild;
}

async function resetMenus() {
  if (Ext.smartMenus) {
    await Ext.removeAllMenus();
    const { t } = await context();
    createMenu({ id: ROOT_ID, title: t("appName"), visible: false });
  } else {
    await buildStaticMenu();
  }
}

// ---------------------------------------------------------------------------
// Firefox for Android has no context menus. There the popup converts the
// selection, and once the user allows access to every site (optional, from
// the popup or the settings page) content/chip.js runs in every page and
// shows a button under a selected amount.

const ALL_SITES = { origins: ["*://*/*"] };
const CHIP = { id: "cv-chip", matches: ALL_SITES.origins, js: ["lib/parse.js", "content/chip.js"], runAt: "document_idle" };

// `fresh` after an install, an update or the user allowing it: the registration
// is replaced, so it lists this version's files, and open pages get the button too.
async function setUpChip({ fresh }) {
  const allowed = await ext.permissions.contains(ALL_SITES).catch(() => false);
  const known = await ext.scripting.getRegisteredContentScripts({ ids: [CHIP.id] });
  if (known.length && (fresh || !allowed)) await ext.scripting.unregisterContentScripts({ ids: [CHIP.id] });
  if (!allowed || (known.length && !fresh)) return;
  await ext.scripting.registerContentScripts([CHIP]);
  if (!fresh) return;
  for (const tab of await ext.tabs.query({})) {
    ext.scripting.executeScript({ target: { tabId: tab.id }, files: CHIP.js }).catch(() => {});
  }
}

async function setUpSelection({ installed }) {
  if (Ext.menus) await resetMenus();
  else await setUpChip({ fresh: installed });
}

ext.runtime.onInstalled.addListener(() => {
  ext.storage.local.remove("rates").catch(() => {}); // 1.x cache (maib only).
  setUpSelection({ installed: true });
});
ext.runtime.onStartup.addListener(() => setUpSelection({ installed: false }));
if (!Ext.menus) {
  ext.permissions.onAdded.addListener(() => setUpChip({ fresh: true }));
  ext.permissions.onRemoved.addListener(() => setUpChip({ fresh: false }));
}

// Chrome's menu lists the bank's currencies and is in the UI language, so
// rebuild it when either changes.
ext.storage.onChanged.addListener(async (changes, area) => {
  if (!Ext.menus || Ext.smartMenus) return;
  if ("bank" in changes || "lang" in changes) return buildStaticMenu();
  if (area === "local") {
    const { bank } = await getSettings();
    if (BankRates.cacheKey(bank) in changes) return buildStaticMenu();
  }
  return undefined;
});

let menuInstance = 0;

if (Ext.smartMenus) {
  ext.menus.onShown.addListener(async (info) => {
    if (!info.contexts.includes("selection")) return;
    const instance = ++menuInstance;
    if (await rebuildMenu(info.selectionText, () => instance === menuInstance)) ext.menus.refresh();
  });
  ext.menus.onHidden.addListener(() => {
    menuInstance++;
  });
}

function onMenuClicked(info, tab) {
  const id = String(info.menuItemId);
  if (id === "cv-settings") {
    ext.runtime.openOptionsPage();
    return;
  }
  const selection = info.selectionText || "";
  let m = /^conv:([A-Z]{3}):([A-Z]{3})$/.exec(id);
  let request = m ? { selection, src: m[1], dst: m[2] } : null;
  if (!request && (m = /^to:([A-Z]{3})$/.exec(id))) request = { selection, src: null, dst: m[1] };
  if (!request) return;
  showConversion({ request, tab, frameId: info.frameId || 0, targetElementId: info.targetElementId });
}

if (Ext.menus) Ext.menus.onClicked.addListener(onMenuClicked);

// ---------------------------------------------------------------------------
// Conversion results: floating box in the page, or a notification where
// content scripts can't run (PDF viewer, about:/chrome:// pages, the stores).

// Chrome's menu doesn't know the source currency: take the detected one, or
// guess and let the box point at the picker.
function resolveSource(request, parsed) {
  if (request.src) return { src: request.src, guessed: false };
  if (parsed && parsed.currency && parsed.currency !== request.dst) return { src: parsed.currency, guessed: false };
  return { src: request.dst === "MDL" ? "EUR" : "MDL", guessed: true };
}

async function computeModel(request, { force = false } = {}) {
  const { lang, t, bank: selected } = await context();
  const bank = Banks.get(request.bank) || selected;
  // No number (an emptied amount field, say) still gets a model, so the box
  // keeps its pickers and shows a hint.
  const parsed = CurrencyParse.parseSelection(request.selection || "");
  const { src, guessed } = resolveSource(request, parsed);
  let result = { rates: null, fetchedAt: null, stale: false, error: null };
  try {
    result = await BankRates.getRates(bank.id, { force });
  } catch (e) {
    result.error = BankRates.errorInfo(e);
  }
  return CurrencyConvert.buildModel({
    selection: request.selection,
    parsed,
    src,
    dst: request.dst,
    srcGuessed: guessed,
    bank,
    banks: bankList(t),
    rates: result.rates,
    fetchedAt: result.fetchedAt,
    stale: result.stale,
    error: result.error ? errorText(result.error, bank, t) : null,
    lang,
    t,
  });
}

async function showConversion({ request, tab, frameId, targetElementId }) {
  const { lang, t } = await context();
  const parsed = CurrencyParse.parseSelection(request.selection);
  const title = parsed ? `${parsed.text}${request.src ? ` ${request.src}` : ""} → ${request.dst}` : t("appName");
  const send = (msg) => ext.tabs.sendMessage(tab.id, msg, { frameId });

  let inPage = false;
  if (tab && tab.id >= 0) {
    try {
      await ext.scripting.executeScript({ target: { tabId: tab.id, frameIds: [frameId] }, files: ["lib/view.js", "content/box.js"] });
      await send({ type: "cv-open", title, request, targetElementId, strings: viewStrings(t), lang });
      inPage = true;
    } catch (e) {
      console.info("can't show the box in this page, using a notification", e);
    }
  }

  const model = await computeModel(request);
  if (inPage) {
    try {
      await send({ type: "cv-result", model });
      return;
    } catch (e) {
      console.info("the box went away, using a notification", e);
    }
  }
  await ext.notifications.create({
    type: "basic",
    iconUrl: ext.runtime.getURL("icons/icon-128.png"),
    title: model.title,
    message: CurrencyConvert.modelToText(model, t),
  });
}

// The box or popup changed the amount, bank or currencies, or asked for fresh
// rates. A bank picked there becomes the default.
async function convertFromBox({ request, force }) {
  const { settings } = await context();
  const changes = {};
  if (request.bank && request.bank !== settings.bank) changes.bank = request.bank;
  const foreign = request.src === "MDL" ? request.dst : request.dst === "MDL" ? request.src : null;
  if (foreign && foreign !== "MDL" && foreign !== settings.lastForeign) changes.lastForeign = foreign;
  await saveSettings(changes);
  return computeModel(request, { force: !!force });
}

// ---------------------------------------------------------------------------
// Keyboard shortcut and the Android selection button: convert the selection
// without the menu (amounts in lei go to the last foreign currency, others to
// lei). The shortcut with nothing selected opens the toolbar converter.

async function readSelection(tabId) {
  const func = () => {
    const el = document.activeElement;
    if (el && /^(INPUT|TEXTAREA)$/.test(el.tagName) && typeof el.selectionStart === "number") {
      return el.value.slice(el.selectionStart, el.selectionEnd);
    }
    return String(getSelection() || "");
  };
  // Frames the extension can't script make allFrames fail; then try the page itself.
  for (const target of [{ tabId, allFrames: true }, { tabId, frameIds: [0] }]) {
    try {
      const results = await ext.scripting.executeScript({ target, func });
      const hit = results.find((r) => r && typeof r.result === "string" && r.result.trim());
      return hit ? { selection: hit.result, frameId: hit.frameId || 0 } : { selection: "", frameId: 0 };
    } catch (e) {
      // Next target.
    }
  }
  return { selection: "", frameId: 0 };
}

// -> { selection, src, dst }, or null if the selection has no amount.
async function selectionRequest(selection) {
  const parsed = selection.trim() && CurrencyParse.parseSelection(selection);
  if (!parsed) return null;
  const { settings } = await context();
  const src = parsed.currency || null;
  return { selection, src, dst: src && src !== "MDL" ? "MDL" : settings.lastForeign };
}

// -> false if the selection has no amount.
async function convertSelection(selection, tab, frameId) {
  const request = await selectionRequest(selection);
  if (request) await showConversion({ request, tab, frameId });
  return !!request;
}

async function convertSelectionInTab(tab) {
  const { selection, frameId } = tab && tab.id >= 0 ? await readSelection(tab.id) : { selection: "", frameId: 0 };
  if (await convertSelection(selection, tab, frameId)) return;
  if (ext.action && ext.action.openPopup) await ext.action.openPopup().catch(() => {});
}

if (ext.commands) {
  ext.commands.onCommand.addListener(async (command, tab) => {
    if (command !== "convert-selection") return;
    const active = tab || (await ext.tabs.query({ active: true, currentWindow: true }))[0];
    convertSelectionInTab(active);
  });
}

// On Android, with no menu and the button perhaps off, the popup starts from
// the amount selected in the current tab (opening the popup grants activeTab),
// and offers the button.
async function popupData() {
  const { lang, t, settings } = await context();
  const data = { lang, strings: viewStrings(t), bank: settings.bank };
  if (Ext.menus) return data;
  data.offer = { text: t("chipOffer"), button: t("chipTurnOn") };
  const [tab] = await ext.tabs.query({ active: true, currentWindow: true }).catch(() => []);
  const request = tab && tab.id >= 0 && (await selectionRequest((await readSelection(tab.id)).selection));
  if (request) {
    const selection = request.selection.trim();
    data.selection = { ...request, selection, src: resolveSource(request, CurrencyParse.parseSelection(selection)).src };
  }
  return data;
}

async function optionsData() {
  const { settings, lang, t } = await context();
  const keys = [
    "optionsTitle", "optIntro", "optBank", "optLang", "optLangAuto", "optSaved", "optDisclaimer", "optPrivacy", "appName",
    "optShortcut", "optShortcutHelp", "optShortcutNone", "optShortcutChange", "optAbout", "extName", "optChip", "optChipHelp",
  ];
  const strings = Object.fromEntries(keys.map((k) => [k, t(k)]));
  // No right-click on Android: the intro points at the selection button.
  if (!Ext.menus) strings.optIntro = t("optIntroTouch");
  return { settings, lang, banks: bankList(t), strings };
}

Ext.onMessage((msg, sender) => {
  if (!msg || typeof msg.type !== "string") return undefined;
  switch (msg.type) {
    case "cv-convert":
      return convertFromBox(msg);
    case "cv-chip":
      return sender.tab ? convertSelection(String(msg.selection || ""), sender.tab, sender.frameId || 0) : undefined;
    case "cv-options":
      return ext.runtime.openOptionsPage();
    case "cv-options-data":
      return optionsData();
    case "cv-popup-data":
      return popupData();
    case "cv-save-settings":
      return saveSettings(msg.settings || {}).then(optionsData);
    default:
      return undefined;
  }
});
